70	// NewHandler builds the public HTTP surface backed by s.
71	func NewHandler(s *store.Store) http.Handler {
72		mux := http.NewServeMux()
73	
74		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
75			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
76		})
77	
78		mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
79			handleRegisterDevice(s, w, r)
80		})
81		// Non-POST verbs on the exact collection path: the method-less pattern is
82		// less specific than POST above, so it only catches the rest and answers a
83		// JSON 404 instead of ServeMux's slash redirect.
84		mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
85			writeError(w, http.StatusNotFound, "unknown device path")
86		})
87		mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
88			writeError(w, http.StatusNotFound, "unknown session path")
89		})
90		mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
91			handleCreateSession(s, w, r)
92		})
93		mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
94			handleDeleteSession(s, w, r)
95		})
96		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
97			handleSessionChanges(s, w, r)
98		})
99		// Any other path under the new namespaces is a JSON 404 rather than
100		// ServeMux's plain-text one: every failure of a new endpoint answers JSON.
101		// Exact method-patterns above take precedence over these subtree patterns.
102		mux.HandleFunc("/v1/devices/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
103			writeError(w, http.StatusNotFound, "unknown device/session path")
104		})
105		mux.HandleFunc("/v1/sessions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
106			writeError(w, http.StatusNotFound, "unknown session path")
107		})
108	
109		mux.HandleFunc("POST /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
110			handlePostChanges(s, w, r)
111		})
112		mux.HandleFunc("GET /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
113			handleListChanges(s, w, r)
114		})
115		mux.HandleFunc("POST /v1/documents/{documentID}/merge", func(w http.ResponseWriter, r *http.Request) {
116			handleMergeChange(s, w, r)
117		})
118		mux.HandleFunc("POST /v1/documents/{documentID}/snapshots", func(w http.ResponseWriter, r *http.Request) {
119			handlePostSnapshot(s, w, r)
120		})
121		mux.HandleFunc("GET /v1/documents/{documentID}/snapshots/{cursor}", func(w http.ResponseWriter, r *http.Request) {
122			handleGetSnapshot(s, w, r)
123		})
124		mux.HandleFunc("POST /v1/documents/{documentID}/restore", func(w http.ResponseWriter, r *http.Request) {
125			handleRestore(s, w, r)
126		})
127		mux.HandleFunc("POST /v1/documents/{documentID}/permissions", func(w http.ResponseWriter, r *http.Request) {
128			handleSetPermission(s, w, r)
129		})
130	
131		// ServeMux treats any empty path segment (the doubled slash in
132		// /v1/documents//..., /v1/devices//sessions or
133		// /v1/sessions//documents/...) as an unclean path and answers with a 307
134		// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
135		// error for an empty identifier, so intercept those paths before the mux
136		// sees them. A trailing slash empties the final id of the device/session
137		// routes and is rejected there for the same reason; the document routes
138		// keep their pre-existing ServeMux behavior.
139		return emptyIDGuard(mux)
140	}
141	
142	// emptyIDGuard rejects requests carrying an empty path identifier with a 400
143	// JSON error instead of letting ServeMux emit its HTML redirect or a
144	// plain-text 404.
145	//
146	// The document family keeps its original rule (an empty documentID, i.e. the
147	// prefix /v1/documents//); other odd paths there retain their old response so
148	// the pre-existing surface is unchanged. The new device/session families are
149	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
150	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
151	func emptyIDGuard(next http.Handler) http.Handler {
152		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
153			p := r.URL.Path
154	
155			documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
156			newFamilySegmentEmpty := false
157			if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
158				newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
159			}
160	
161			if documentSegmentEmpty || newFamilySegmentEmpty {
162				writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
163				return
164			}
165			next.ServeHTTP(w, r)
166		})
167	}
