169	// Handler exposes the HTTP surface over a private in-memory store. Use
170	// NewHandler with a durable store for real deployments.
171	func Handler() http.Handler {
172		s, err := store.Open("")
173		if err != nil {
174			log.Fatalf("open in-memory store: %v", err)
175		}
176		return NewHandler(s)
177	}
