179	// decodeJSONBody enforces the strict POST contract shared by every JSON
180	// endpoint: Content-Type must be application/json, the body is capped at
181	// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
182	// may follow it. Any violation writes a 400 JSON error and returns false; the
183	// caller returns immediately, so no handler reaches the store with malformed
184	// input and rejected requests write nothing.
185	func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
186		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
187		if err != nil || mediaType != "application/json" {
188			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
189			return false
190		}
191	
192		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
193		dec := json.NewDecoder(r.Body)
194		if err := dec.Decode(dst); err != nil {
195			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
196			return false
197		}
198		// Reject trailing data after the JSON value.
199		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
200			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
201			return false
202		}
203		return true
204	}
