206	func handleRegisterDevice(s *store.Store, w http.ResponseWriter, r *http.Request) {
207		var req deviceRequest
208		if !decodeJSONBody(w, r, &req) {
209			return
210		}
211		if req.DeviceID == "" {
212			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
213			return
214		}
215	
216		created, err := s.RegisterDevice(req.DeviceID)
217		if err != nil {
218			writeError(w, http.StatusInternalServerError, "failed to register device")
219			return
220		}
221	
222		writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
223	}
