225	func handleCreateSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
226		deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty
227	
228		var req sessionRequest
229		if !decodeJSONBody(w, r, &req) {
230			return
231		}
232		if req.SessionID == "" {
233			writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
234			return
235		}
236	
237		created, err := s.CreateSession(deviceID, req.SessionID)
238		if err != nil {
239			var conflict *store.ErrSessionConflict
240			switch {
241			case errors.Is(err, store.ErrDeviceNotFound):
242				writeError(w, http.StatusNotFound, "device not found")
243			case errors.As(err, &conflict):
244				writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
245			default:
246				writeError(w, http.StatusInternalServerError, "failed to create session")
247			}
248			return
249		}
250	
251		writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
252	}
