254	func handleDeleteSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
255		deviceID := r.PathValue("deviceId")   // route pattern + guard guarantee non-empty
256		sessionID := r.PathValue("sessionId") // route pattern + guard guarantee non-empty
257	
258		if err := s.DeleteSession(deviceID, sessionID); err != nil {
