270	func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
271		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
272	
273		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
274		if err != nil || mediaType != "application/json" {
275			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
276			return
277		}
278	
279		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
280		var req postRequest
281		dec := json.NewDecoder(r.Body)
282		if err := dec.Decode(&req); err != nil {
283			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
284			return
285		}
286		// Reject trailing data after the JSON object.
287		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
288			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
289			return
290		}
291	
292		if req.DeviceID == "" {
293			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
294			return
295		}
296		if len(req.Changes) == 0 {
297			writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
298			return
299		}
300	
301		changes := make([]store.Change, len(req.Changes))
302		seen := make(map[string]struct{}, len(req.Changes))
303		for i, c := range req.Changes {
304			if c.ID == "" {
305				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
306				return
307			}
308			if len(c.Payload) == 0 {
309				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
310				return
311			}
312			if _, dup := seen[c.ID]; dup {
313				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
314				return
315			}
316			seen[c.ID] = struct{}{}
317			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
318		}
319	
320		results, err := s.PostChanges(documentID, changes)
321		if err != nil {
322			var conflict *store.ErrConflict
323			if errors.As(err, &conflict) {
324				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
325				return
326			}
327			writeError(w, http.StatusInternalServerError, "failed to commit changes")
328			return
329		}
330	
331		writeJSON(w, http.StatusOK, map[string]any{"results": results})
332	}
