334	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
335		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
336	
337		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
338		if err != nil || mediaType != "application/json" {
339			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
340			return
341		}
342	
343		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
344		var req mergeRequest
345		dec := json.NewDecoder(r.Body)
346		if err := dec.Decode(&req); err != nil {
347			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
348			return
349		}
350		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
351			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
352			return
353		}
354	
355		if req.DeviceID == "" {
356			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
357			return
358		}
359		// baseCursor must be present and a non-negative integer (no fractions,
360		// strings, booleans or null).
361		if len(req.BaseCursor) == 0 {
362			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
363			return
364		}
365		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
366		if !ok {
367			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
368			return
369		}
370		if req.Change == nil {
371			writeError(w, http.StatusBadRequest, "change must be an object")
372			return
373		}
374		if req.Change.ID == "" {
375			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
376			return
377		}
378		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
379			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
380			return
381		}
382	
383		result, err := s.MergeChange(documentID, baseCursor, store.Change{
384			ID:       req.Change.ID,
385			DeviceID: req.DeviceID,
386			Payload:  req.Change.Payload,
387		})
388		if err != nil {
389			var conflict *store.ErrConflict
390			switch {
391			case errors.Is(err, store.ErrStaleCursor):
392				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
393				return
394			case errors.As(err, &conflict):
395				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
396				return
397			default:
398				writeError(w, http.StatusInternalServerError, "failed to merge change")
399				return
400			}
401		}
402	
403		writeJSON(w, http.StatusOK, result)
404	}
