406	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
407		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
408	
409		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
410		if err != nil || mediaType != "application/json" {
411			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
412			return
413		}
414	
415		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
416		var req snapshotPostRequest
417		dec := json.NewDecoder(r.Body)
418		if err := dec.Decode(&req); err != nil {
419			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
420			return
421		}
422		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
423			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
424			return
425		}
426	
427		cursor, ok := parseNonNegativeInt(req.Cursor)
428		if !ok {
429			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
430			return
431		}
432		if len(req.State) == 0 {
433			writeError(w, http.StatusBadRequest, "state is required")
434			return
435		}
436	
437		created, err := s.PutSnapshot(documentID, cursor, req.State)
438		if err != nil {
439			var conflict *store.ErrSnapshotConflict
440			switch {
441			case errors.Is(err, store.ErrSnapshotBase):
442				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
443				return
444			case errors.As(err, &conflict):
445				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
446				return
447			default:
448				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
449				return
450			}
451		}
452	
453		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
454	}
