456	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
457		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
458	
459		cursor, ok := parseCursorPath(r.PathValue("cursor"))
460		if !ok {
461			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
462			return
463		}
464	
465		state, err := s.GetSnapshot(documentID, cursor)
466		if err != nil {
467			if errors.Is(err, store.ErrSnapshotNotFound) {
468				writeError(w, http.StatusNotFound, "snapshot not found")
469				return
470			}
471			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
472			return
473		}
474	
475		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
476	}
