478	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
479		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
480	
481		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
482		if err != nil || mediaType != "application/json" {
483			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
484			return
485		}
486	
487		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
488		var req restoreRequest
489		dec := json.NewDecoder(r.Body)
490		if err := dec.Decode(&req); err != nil {
491			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
492			return
493		}
494		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
495			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
496			return
497		}
498	
499		if req.DeviceID == "" {
500			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
501			return
502		}
503		if req.ChangeID == "" {
504			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
505			return
506		}
507		// snapshotCursor must be present and a positive integer (no fractions,
508		// strings, booleans, null or zero).
509		if len(req.SnapshotCursor) == 0 {
510			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
511			return
512		}
513		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
514		if !ok {
515			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
516			return
517		}
518	
519		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
520		if err != nil {
521			var conflict *store.ErrRestoreConflict
522			switch {
523			case errors.Is(err, store.ErrSnapshotNotFound):
524				writeError(w, http.StatusNotFound, "snapshot not found")
525				return
526			case errors.As(err, &conflict):
527				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
528				return
529			default:
530				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
531				return
532			}
533		}
534	
535		writeJSON(w, http.StatusOK, result)
536	}
