538	// handleSetPermission grants or revokes a registered device's access to one
539	// document. Devices start authorized, so the first revoke is the first write;
540	// repeating the current state is idempotent (changed=false). A rejected
541	// request (bad content type, malformed JSON, trailing content, empty or
542	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
543	// unregistered device is a 404 JSON error.
544	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
545		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
546	
547		var req permissionRequest
548		if !decodeJSONBody(w, r, &req) {
549			return
550		}
551		if req.DeviceID == "" {
552			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
553			return
554		}
555		var authorized bool
556		switch req.Action {
557		case "grant":
558			authorized = true
559		case "revoke":
560			authorized = false
561		default:
562			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
563			return
564		}
565	
566		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
567		if err != nil {
568			if errors.Is(err, store.ErrDeviceNotFound) {
569				writeError(w, http.StatusNotFound, "device not found")
570				return
571			}
572			writeError(w, http.StatusInternalServerError, "failed to update permission")
573			return
574		}
575	
576		writeJSON(w, http.StatusOK, map[string]any{
577			"deviceId":   req.DeviceID,
578			"authorized": authorized,
579			"changed":    changed,
580		})
581	}
582	
583	// parseCursorPath reports whether raw is a decimal non-negative integer and
584	// returns its value. Signs, fractions and other adornments are rejected.
585	func parseCursorPath(raw string) (int64, bool) {
586		if raw == "" {
587			return 0, false
588		}
589		for _, c := range raw {
590			if c < '0' || c > '9' {
591				return 0, false
592			}
593		}
594		n, err := strconv.ParseInt(raw, 10, 64)
595		if err != nil {
596			return 0, false
597		}
598		return n, true
599	}
600	
601	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
602	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
603		var n int64
604		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
605			return 0, false
606		}
607		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
608		// require the literal to contain no fraction or exponent.
609		trimmed := strings.TrimSpace(string(raw))
610		if trimmed == "" || trimmed[0] == '-' {
611			return 0, false
612		}
613		for _, c := range trimmed {
614			if c < '0' || c > '9' {
615				return 0, false
616			}
617		}
618		return n, true
619	}
620	
621	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
622	// strings, booleans, null and negative numbers are rejected.
623	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
624		n, ok := parseNonNegativeInt(raw)
625		if !ok || n < 1 {
626			return 0, false
627		}
628		return n, true
629	}
630	
631	// isJSONObject reports whether raw decodes to a JSON object (not null, an
632	// array or a scalar).
633	func isJSONObject(raw json.RawMessage) bool {
634		var m map[string]json.RawMessage
635		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
636			return false
637		}
638		return true
639	}
640	
641	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
642		documentID := r.PathValue("documentID")
643	
644		after, limit, ok := parseChangesQuery(w, r)
645		if !ok {
646			return
647		}
648	
649		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
650		if err != nil {
651			writeError(w, http.StatusInternalServerError, "failed to list changes")
652			return
653		}
654	
655		writeChangesPage(w, changes, nextCursor)
656	}
657	
658	// handleSessionChanges is the session-scoped view of the existing change log:
659	// both path identifiers must be non-empty (the empty-segment guard rejects
660	// those before routing) and the session must currently exist, after which the
661	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
662	// the session's device has been revoked permission for the document, which is
663	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
664	// read; the change log itself is untouched.
665	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
666		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
667		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
668	
669		// Malformed query parameters are a request-shape error (400) checked
670		// before the resource lookup (404), matching the snapshot GET ordering.
671		after, limit, ok := parseChangesQuery(w, r)
672		if !ok {
673			return
674		}
675	
676		deviceID, err := s.SessionDevice(sessionID)
677		if err != nil {
678			if errors.Is(err, store.ErrSessionNotFound) {
679				writeError(w, http.StatusNotFound, "session not found")
680				return
681			}
682			writeError(w, http.StatusInternalServerError, "failed to look up session")
683			return
684		}
685	
686		authorized, err := s.DocumentAuthorized(documentID, deviceID)
687		if err != nil {
688			writeError(w, http.StatusInternalServerError, "failed to look up permission")
689			return
690		}
691		if !authorized {
692			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
693			return
694		}
695	
696		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
697		if err != nil {
698			writeError(w, http.StatusInternalServerError, "failed to list changes")
699			return
700		}
701	
702		writeChangesPage(w, changes, nextCursor)
703	}
704	
705	// parseChangesQuery parses the shared after/limit pagination parameters,
706	// writing the documented 400 on an illegal value. It is shared by the
707	// document-scoped and session-scoped change listings so their query semantics
708	// cannot drift apart.
709	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
710		q := r.URL.Query()
711	
712		after = 0
713		if raw := q.Get("after"); raw != "" {
714			v, err := strconv.ParseInt(raw, 10, 64)
715			if err != nil || v < 0 {
716				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
717				return 0, 0, false
718			}
719			after = v
720		}
721	
722		limit = defaultListLimit
723		if raw := q.Get("limit"); raw != "" {
724			v, err := strconv.ParseInt(raw, 10, 64)
725			if err != nil || v < 1 || v > maxListLimit {
726				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
727				return 0, 0, false
728			}
729			limit = v
730		}
731	
732		return after, limit, true
733	}
734	
735	// writeChangesPage renders a change listing page in the shared response shape.
736	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
737		writeJSON(w, http.StatusOK, map[string]any{
738			"changes":    changes,
739			"nextCursor": nextCursor,
740		})
741	}
742	
743	func writeJSON(w http.ResponseWriter, status int, v any) {
744		w.Header().Set("Content-Type", "application/json")
745		w.WriteHeader(status)
746		_ = json.NewEncoder(w).Encode(v)
747	}
748	
749	func writeError(w http.ResponseWriter, status int, message string) {
750		writeJSON(w, status, map[string]string{"error": message})
751	}
752

